def rotate_half(x):
    first = x[..., :x.shape[-1] // 2]
    second = x[..., x.shape[-1] // 2:]
    return torch.cat((-second, first), dim=-1)


def _apply_gqa_rope(query, key, position_embeddings, rotary_interleaved, head_dim):
    if position_embeddings is None:
        return (query, key)
    cos, sin = position_embeddings
    if rotary_interleaved:
        return apply_rotary_pos_emb_interleave(query, key, cos, sin, unsqueeze_dim=2)
    if cos.shape[-1] >= head_dim:
        return apply_rotary_pos_emb(query, key, cos, sin, unsqueeze_dim=2)
    rotary_dim = cos.shape[-1]
    query_rot, query_pass = (query[..., :rotary_dim], query[..., rotary_dim:])
    key_rot, key_pass = (key[..., :rotary_dim], key[..., rotary_dim:])
    cos = cos.unsqueeze(2)
    sin = sin.unsqueeze(2)
    query = torch.cat((query_rot * cos + rotate_half(query_rot) * sin, query_pass), dim=-1)
    key = torch.cat((key_rot * cos + rotate_half(key_rot) * sin, key_pass), dim=-1)
    return (query, key)


def _projections_can_fuse(projections):
    biases = tuple((projection.bias for projection in projections))
    return len({projection.in_features for projection in projections}) == 1 and len({projection.weight.requires_grad for projection in projections}) == 1 and (all((bias is None for bias in biases)) or all((bias is not None for bias in biases))) and (biases[0] is None or len({bias.requires_grad for bias in biases}) == 1)


_COMPRESSED_CAUSAL_MASKS = {}

_COMPRESSED_CAUSAL_MASK_SIZE = 2048

def _get_compressed_causal_mask(device: torch.device) -> torch.Tensor:
    """Return the cached mask required by NPU left-up causal sparse mode."""
    mask = _COMPRESSED_CAUSAL_MASKS.get(device)
    if mask is None:
        mask = torch.triu(torch.ones((_COMPRESSED_CAUSAL_MASK_SIZE, _COMPRESSED_CAUSAL_MASK_SIZE), dtype=torch.bool, device=device), diagonal=1)
        _COMPRESSED_CAUSAL_MASKS[device] = mask
    return mask

def run_qwen3_moe_flash_attention(module: nn.Module, query: torch.Tensor, key: torch.Tensor, value: torch.Tensor, attention_mask: torch.Tensor | None, dropout: float=0.0, scaling: float | None=None, **kwargs: Any) -> tuple[torch.Tensor, None]:
    """Run Qwen3-MoE grouped-query attention with the Ascend Flash Attention kernel.

    Boolean model-facing masks follow the Transformers convention: ``True``
    marks an allowed query-key pair. This function performs the sole conversion
    to the Ascend kernel convention, where ``True`` marks a blocked pair.

    This is the ``attention_interface`` that
    ``replacements.replace_qwen3_moe_flash_attention`` hands to
    ``modules.GQAAttention`` so the replaced module keeps the Qwen mask/cache
    calling convention (compressed causal mask, ``sparse_mode`` selection).
    """
    import torch_npu
    del kwargs
    if attention_mask is None:
        attention_mask = _get_compressed_causal_mask(query.device)
        sparse_mode = 2
    else:
        if attention_mask.ndim == 4:
            attention_mask = attention_mask[:, :, :, :key.shape[-2]]
        if attention_mask.dtype == torch.bool:
            attention_mask = torch.logical_not(attention_mask).to(query.device)
        else:
            attention_mask = attention_mask.bool().to(query.device)
        sparse_mode = 0
    sparse_kwargs = {}
    if sparse_mode == 0 and getattr(module, 'is_causal', True) and (query.shape[-2] == key.shape[-2]):
        sparse_kwargs['next_tockens'] = 0
    attention_output = torch_npu.npu_fusion_attention(query, key, value, head_num=query.shape[1], input_layout='BNSD', atten_mask=attention_mask, keep_prob=1 - dropout, scale=scaling, sparse_mode=sparse_mode, **sparse_kwargs)[0]
    return (attention_output.transpose(1, 2).contiguous(), None)


